static std::vector<Point> cgal_intersect_polygons(const Polygon& lhs, const Polygon& rhs) {
    ScopedTimer timer(TimedOp::CgalIntersection);
    std::vector<Polygon_with_holes> pieces;
    CGAL::intersection(lhs, rhs, std::back_inserter(pieces));
    if (pieces.empty()) {
        return {};
    }

    const Polygon_with_holes* best = &pieces.front();
    double best_area = std::abs(CGAL::to_double(best->outer_boundary().area()));
    for (const Polygon_with_holes& piece : pieces) {
        const double area = std::abs(CGAL::to_double(piece.outer_boundary().area()));
        if (area > best_area) {
            best_area = area;
            best = &piece;
        }
    }

    const Polygon& outer = best->outer_boundary();
    return std::vector<Point>(outer.vertices_begin(), outer.vertices_end());
}

